"""Rules for text-to-image prompts generated by Script Craft (Issue #28).

Image models are easily confused by writing instructions inside a prompt.  A
prompt that mentions an aspect ratio, a split-screen comparison, or "text
reading ..." often produces exactly those artefacts.  These rules are applied
in two places:

* the Script Craft system/tool prompts, so the model avoids them up front;
* :func:`sanitize_image_prompt`, a deterministic cleanup pass for every image
  prompt that enters a project (AI generation, chat edits, JSON/text import).
"""

from __future__ import annotations

import re

IMAGE_PROMPT_RULES = """Image prompt rules (apply to every segment):
- Describe only visual subjects, lighting, palette and camera language.
- Never request text of any kind: no words, letters, numbers, captions,
  subtitles, title cards, labels, signage with writing, typography, logos or
  watermarks.
- Never request a comparison image: no split-screen, side-by-side, diptych,
  before-and-after, two-panel or "X vs Y" composition. One single scene only.
- Never mention an aspect ratio, frame size, resolution or orientation
  (16:9, 9:16, 4:3, 1:1, vertical, landscape, widescreen, --ar ...).
- Do not quote text that should appear inside the image."""


_ASPECT_RATIO = re.compile(
    r"(?<![\w:])(?:16\s*:\s*9|9\s*:\s*16|4\s*:\s*3|3\s*:\s*4|"
    r"1\s*:\s*1|21\s*:\s*9|2\s*:\s*3|3\s*:\s*2)(?![\w:])",
    re.IGNORECASE,
)
_ASPECT_PHRASE = re.compile(
    r"\b(?:with\s+an?\s+)?(?:image\s+|video\s+|frame\s+)?"
    r"aspect\s+ratio(?:\s+of)?\s*[^,.;]*",
    re.IGNORECASE,
)
_ORIENTATION_PHRASE = re.compile(
    r"\b(?:vertical|horizontal|portrait|landscape|square|widescreen)\s+"
    r"(?:format|orientation|aspect\s+ratio|framing)\b",
    re.IGNORECASE,
)
_CLI_AR = re.compile(r"(?:^|\s)--ar\s+\S+", re.IGNORECASE)
_RESOLUTION = re.compile(
    r"\b\d{3,4}\s*[x×]\s*\d{3,4}\s*(?:px|pixels?)?\b", re.IGNORECASE
)

_COMPARISON = re.compile(
    r"\b(?:split[\s-]?screen|side[\s-]?by[\s-]?side|before[\s-]?and[\s-]?after|"
    r"comparison\s+(?:image|shot|view|panel|of)|diptych|triptych|"
    r"two[\s-]?panel|multi[\s-]?panel|versus\s+composition)\b[^,.;]*",
    re.IGNORECASE,
)

# "a sign reading HELLO", "with the words ...", "caption that says ..."
_TEXT_INSTRUCTION = re.compile(
    r"\b(?:with|containing|showing|displaying|featuring|including|bearing)\s+"
    r"(?:the\s+)?(?:text|words?|letters?|numbers?|caption|subtitle|title|"
    r"label|signage|typography|writing|lettering)\b[^,.;]*",
    re.IGNORECASE,
)
_TEXT_READING = re.compile(
    r"\b(?:text|words?|letters?|caption|subtitle|title|label|sign|signage|"
    r"typography|writing|lettering)\s+"
    r"(?:reading|that\s+says|which\s+says|saying|spelling\s+out)\b[^,.;]*",
    re.IGNORECASE,
)
_TEXT_FREE_PHRASE = re.compile(
    r"\b(?:no|without|zero|free\s+of)\s+"
    r"(?:any\s+)?(?:visible\s+|readable\s+|legible\s+)?"
    r"(?:text|words?|letters?|captions?|subtitles?|typography|logos?)\b",
    re.IGNORECASE,
)
_STANDALONE_TEXT = re.compile(
    r"\b(?:visible\s+|printed\s+|written\s+|legible\s+)?"
    r"(?:text|lettering|typography|title\s+card|subtitle|caption)\b",
    re.IGNORECASE,
)
_ALL_CAPS_AFTER_READING = re.compile(
    r"\b(?:reading|spelling\s+out|that\s+says|which\s+says|saying)\s+"
    r"(?:the\s+)?[A-Z0-9][A-Z0-9\s'’\-]{1,80}",
)
_QUOTED = re.compile(r"[\"“”][^\"“”]{1,160}[\"“”]")
_EMPTY_PUNCT = re.compile(r"\s+([,.;:])")
_REPEATED_PUNCT = re.compile(r"([,.;:])(?:\s*[,.;:])+")
_SPACES = re.compile(r"\s{2,}")


def sanitize_image_prompt(prompt: str) -> str:
    """Remove text/comparison/aspect-ratio instructions from an image prompt.

    The function is deliberately conservative about normal prose: it only
    strips explicit instructions and artefacts, then collapses the remaining
    whitespace.  An empty result is allowed (the renderer can still ask the
    user for an image).
    """
    if not prompt:
        return ''

    cleaned = str(prompt)
    cleaned = _CLI_AR.sub(' ', cleaned)
    cleaned = _ASPECT_RATIO.sub(' ', cleaned)
    cleaned = _ASPECT_PHRASE.sub(' ', cleaned)
    cleaned = _ORIENTATION_PHRASE.sub(' ', cleaned)
    cleaned = _RESOLUTION.sub(' ', cleaned)
    cleaned = _COMPARISON.sub(' ', cleaned)
    cleaned = _TEXT_INSTRUCTION.sub(' ', cleaned)
    cleaned = _TEXT_READING.sub(' ', cleaned)
    cleaned = _TEXT_FREE_PHRASE.sub(' ', cleaned)
    cleaned = _QUOTED.sub(' ', cleaned)
    cleaned = _STANDALONE_TEXT.sub(' ', cleaned)
    cleaned = _ALL_CAPS_AFTER_READING.sub(' ', cleaned)

    cleaned = _EMPTY_PUNCT.sub(r'\1', cleaned)
    cleaned = _REPEATED_PUNCT.sub(r'\1', cleaned)
    cleaned = _SPACES.sub(' ', cleaned)
    return cleaned.strip(' ,;:\n\t')


def merge_prompt_rules(system_prompt: str = '') -> str:
    """Append the image-prompt contract to a Script Craft system prompt."""
    base = (system_prompt or '').strip()
    if not base:
        return IMAGE_PROMPT_RULES
    return f"{base}\n\n{IMAGE_PROMPT_RULES}"
